import { replaceVariables } from '@mintlify/common';
import fs from 'node:fs/promises';
import path from 'node:path';

import { checkFiles, parseFile } from './files.js';
import { applyEdits, selectEdits, toPosition } from './mdx.js';
import { buildFindings } from './rules/build.js';
import { RULES } from './rules/index.js';
import { PARSE_ERROR } from './rules/parseError.js';
import { loadSite } from './site.js';
import {
  GROUPS,
  type Change,
  type Diagnostic,
  type DiagnosticSource,
  type FileEdit,
  type FileRule,
  type Finding,
  type Rule,
  type Site,
} from './types.js';

export class UsageError extends Error {}

const ruleList = () => RULES.map(({ id }) => id).join(', ');

const matchToken = (token: string): Rule[] => {
  if (token === 'all') return RULES;
  const rule = RULES.find(({ id }) => id === token);
  if (rule) return [rule];
  if ((GROUPS as string[]).includes(token)) {
    return RULES.filter(({ group }) => group === token);
  }
  throw new UsageError(
    `unknown rule or group "${token}". Groups: all, ${GROUPS.join(', ')}. Rules: ${ruleList()}`
  );
};

/** Every rule, minus --disable, plus --enable. parse-error is the engine's own, not selectable. */
export const selectRules = ({
  enable = [],
  disable = [],
}: {
  enable?: string[];
  disable?: string[];
}): Rule[] => {
  if ([...disable, ...enable].includes(PARSE_ERROR.id)) {
    throw new UsageError(`${PARSE_ERROR.id} always runs and can't be disabled`);
  }
  const selected = new Set(RULES);
  for (const token of disable) for (const rule of matchToken(token)) selected.delete(rule);
  for (const token of enable) for (const rule of matchToken(token)) selected.add(rule);
  return RULES.filter((rule) => selected.has(rule));
};

const toDiagnostic = (source: DiagnosticSource, finding: Finding): Diagnostic => ({
  ...finding,
  rule: source.id,
  group: source.group,
  severity: finding.severity ?? source.severity,
});

const RULE_ORDER = new Map(RULES.map(({ id }, index) => [id, index]));

const sortDiagnostics = (diagnostics: Diagnostic[]) =>
  diagnostics.sort(
    (a, b) =>
      (a.file < b.file ? -1 : a.file > b.file ? 1 : 0) ||
      (a.line ?? 0) - (b.line ?? 0) ||
      (a.column ?? 0) - (b.column ?? 0) ||
      (RULE_ORDER.get(a.rule) ?? 0) - (RULE_ORDER.get(b.rule) ?? 0)
  );

/** Adds findings for a rule unless a diagnostic of that rule already has the same key. */
const merge = (
  diagnostics: Diagnostic[],
  source: DiagnosticSource,
  extra: Finding[],
  key: (item: Pick<Diagnostic, 'file' | 'message'>) => string
) => {
  const reported = new Set(diagnostics.filter((item) => item.rule === source.id).map(key));
  for (const finding of extra) {
    if (reported.has(key(finding))) continue;
    reported.add(key(finding));
    diagnostics.push(toDiagnostic(source, finding));
  }
};

const addParseErrors = (site: Site, diagnostics: Diagnostic[], extra: Finding[]) =>
  merge(
    diagnostics,
    PARSE_ERROR,
    extra.filter(({ file }) => !site.selected || site.selected.has(file)),
    ({ file }) => file
  );

const fileRulesOf = (rules: Rule[]) =>
  rules.filter((rule): rule is FileRule => rule.scope === 'file');

const runSiteRules = async (
  site: Site,
  rules: Rule[],
  needsBuild: boolean,
  diagnostics: Diagnostic[]
) => {
  for (const rule of rules) {
    if (rule.scope !== 'site' || Boolean(rule.needsBuild) !== needsBuild) continue;
    for (const finding of await rule.check(site)) diagnostics.push(toDiagnostic(rule, finding));
  }
};

/** Runs every selected rule that doesn't need the build. */
export const runChecks = async (site: Site, rules: Rule[]) => {
  const diagnostics = await checkFiles(site, fileRulesOf(rules));
  await runSiteRules(site, rules, false, diagnostics);
  return sortDiagnostics(diagnostics);
};

/** Adds the build's findings to a site whose build has run. */
export const runBuildChecks = async (site: Site, rules: Rule[], diagnostics: Diagnostic[]) => {
  await runSiteRules(site, rules, true, diagnostics);
  // The file pass already reported files it couldn't parse; the build adds the rest
  addParseErrors(site, diagnostics, buildFindings(site, 'parse-error'));
  return sortDiagnostics(diagnostics);
};

const parseLevel = (file: string, content: string, baseDir: string) => {
  const parsed = parseFile(file, content, baseDir);
  return 'error' in parsed ? 0 : parsed.approximate ? 1 : 2;
};

/** Applies every fix that doesn't overlap an earlier fix in the same file, writing each Markdown file only when its fixed content parses at least as well as before. */
export const applyFixes = async (site: Site, diagnostics: Diagnostic[]): Promise<Change[]> => {
  const read = (file: string) => site.read(file) ?? '';
  const chosen = new Map<string, { fix: FileEdit; change: Change }[]>();
  const overlaps = ({ file, start, end }: FileEdit) =>
    (chosen.get(file) ?? []).some(({ fix }) => start < fix.end && fix.start < end);

  for (const { rule, fix } of diagnostics) {
    if (!fix || overlaps(fix)) continue;
    const content = read(fix.file);
    const change = {
      rule,
      file: fix.file,
      ...toPosition(content, fix.start),
      before: content.slice(fix.start, fix.end),
      after: fix.text,
    };
    chosen.set(fix.file, [...(chosen.get(fix.file) ?? []), { fix, change }]);
  }

  const snippets = new Set(
    site.files.filter(({ kind }) => kind === 'snippet').map(({ file }) => file)
  );
  const level = (file: string, content: string) =>
    parseLevel(
      file,
      snippets.has(file) ? replaceVariables(content, site.variables) : content,
      site.baseDir
    );

  const applied: Change[] = [];
  for (const [file, picks] of chosen) {
    const content = read(file);
    const updated = applyEdits(content, selectEdits(picks.map(({ fix }) => fix)));
    if (/\.mdx?$/.test(file) && level(file, updated) < level(file, content)) {
      continue;
    }
    await fs.writeFile(path.join(site.baseDir, file), updated);
    applied.push(...picks.map(({ change }) => change));
  }
  return applied;
};

// Fixes can unlock others (a self-closed <br> lets a page parse), so --fix runs a few passes
const MAX_FIX_PASSES = 5;

/**
 * Loads the site and runs the selected rules. With fix, applies the fixes, rechecks only the
 * files that changed for further fixes, then runs every rule once more for the final report.
 */
export const checkSite = async (
  baseDir: string,
  rules: Rule[],
  options: { selected?: ReadonlySet<string>; localSchema: boolean; fix: boolean }
) => {
  const fixed: Change[] = [];
  let site = await loadSite(baseDir, options);
  const { selected } = options;
  if (selected && !site.files.some(({ file }) => selected.has(file))) {
    throw new UsageError(
      `none of the given files are pages or snippets of this site: ${[...selected].join(', ')}`
    );
  }
  const diagnostics = await runChecks(site, rules);
  if (!options.fix) return { site, diagnostics, fixed };

  // Only file rules offer fixes, so passes after the first recheck just the files that changed
  let pending = diagnostics;
  for (let pass = 0; pass < MAX_FIX_PASSES; pass++) {
    const changes = await applyFixes(site, pending);
    if (changes.length === 0) break;
    fixed.push(...changes);
    site = await loadSite(baseDir, options);
    const changed = new Set(changes.map(({ file }) => file));
    pending = sortDiagnostics(await checkFiles({ ...site, selected: changed }, fileRulesOf(rules)));
  }
  if (fixed.length === 0) return { site, diagnostics, fixed };
  return { site, diagnostics: await runChecks(site, rules), fixed };
};
